"""Content-addressed traces of tagged C++ examples, generated by the course's tracer.

Each trace lives at ``<traces>/<key>.json``, where the key hashes the snippet, its
template override, whether it shows types, and the tracer revision (which covers the pinned
toolchain).
Languages that share a snippet share its trace. CI caches the directory, so only
changed examples are traced again.
"""
from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
from pathlib import Path
import subprocess
import sys
import tempfile

from .visualization_config import VisualizationOptions, contained_path
from .visualization_tags import Tag, scan_document


class VisualizationError(Exception):
    pass


@dataclass(frozen=True)
class TaggedExample:
    path: Path
    tag: Tag

    def location(self, repo: Path) -> str:
        return f'{self.path.relative_to(repo)}:{self.tag.line}: [VIS]'


def markdown_files(repo: Path, options: VisualizationOptions) -> list[Path]:
    files = set()
    for root in options.roots:
        for path in contained_path(repo, root).rglob('*.md'):
            if not path.resolve().is_relative_to(repo.resolve()):
                raise VisualizationError(f'{path}: [VIS] source symlink escapes repository')
            files.add(path)
    return sorted(files)


def trace_key(source: str, template: str | None, revision: str, types: bool = False) -> str:
    # A tag without `types` keeps the key it had before the attribute existed.
    payload = json.dumps([revision, template, source] + ['types'] * types, ensure_ascii=False)
    return hashlib.sha256(payload.encode('utf-8')).hexdigest()


def generate_command(options: VisualizationOptions) -> str:
    return (f'nix develop .#{options.shell} --command python3 '
            'course_maintenance/publish.py visualizations generate --course-repo .')


def _command(argv: list[str], *, timeout=120) -> str:
    try:
        result = subprocess.run(argv, capture_output=True, text=True,
                                encoding='utf-8', timeout=timeout, check=False)
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise VisualizationError(f'command failed ({argv[0]}): {exc}') from exc
    if result.returncode:
        detail = (result.stderr or result.stdout).strip()
        raise VisualizationError(f'{Path(argv[1]).name} exited {result.returncode}: {detail[-2000:]}')
    return result.stdout


class Tracer:
    """The course-owned ``generate.py`` adapter, run as a separate process."""

    def __init__(self, repo: Path, options: VisualizationOptions, command=None):
        self.script = contained_path(repo, options.templates + '/generate.py')
        self.command = command or _command
        self._revision = None

    @property
    def revision(self) -> str:
        if self._revision is None:
            revision = self.command([sys.executable, str(self.script), 'revision']).strip()
            if not revision:
                raise VisualizationError('tracer revision must not be empty')
            self._revision = revision
        return self._revision

    def trace(self, source: Path, template: str | None, types: bool = False) -> str:
        argv = [sys.executable, str(self.script), 'trace', '--source', str(source)]
        if template:
            argv += ['--template', template]
        if types:
            argv.append('--types')
        output = self.command(argv, timeout=600)
        try:
            json.loads(output)
        except ValueError as exc:
            raise VisualizationError(f'tracer printed invalid JSON: {exc}') from exc
        return output


class TraceStore:
    """Where the trace of a tag lives, whether or not it has been generated."""

    def __init__(self, repo: Path, options: VisualizationOptions, command=None):
        self.directory = contained_path(repo, options.traces)
        self.tracer = Tracer(repo, options, command)

    def path(self, tag: Tag) -> Path:
        key = trace_key(tag.source.source, tag.template, self.tracer.revision, tag.types)
        return self.directory / f'{key}.json'

    def load(self, tag: Tag) -> str | None:
        path = self.path(tag)
        return path.read_text(encoding='utf-8') if path.is_file() else None


class Traces:
    """Tagged examples of a course, and where their traces are stored."""

    def __init__(self, repo: Path, config, selected_paths=None, *, command=None):
        self.repo = repo
        self.options: VisualizationOptions = config.visualizations
        self.store = TraceStore(repo, self.options, command)
        self.directory = self.store.directory
        self.tracer = self.store.tracer
        self.examples: list[TaggedExample] = []
        self.errors: list[str] = []
        selected = None if selected_paths is None else {Path(p).resolve() for p in selected_paths}
        for path in markdown_files(repo, self.options):
            if selected is None or path.resolve() in selected:
                scanned = scan_document(path.read_text(encoding='utf-8'), path.relative_to(repo))
                self.errors.extend(scanned.errors)
                self.examples.extend(TaggedExample(path, tag) for tag in scanned.tags)

    def path(self, example: TaggedExample) -> Path:
        return self.store.path(example.tag)

    def cache_key(self) -> str:
        """One key for the whole trace set, for restoring the CI cache."""
        keys = sorted({self.path(example).stem for example in self.examples})
        return hashlib.sha256('\n'.join(keys).encode()).hexdigest()

    def missing(self) -> list[str]:
        command = generate_command(self.options)
        return [f'{example.location(self.repo)} missing trace; run `{command}`'
                for example in self.examples if not self.path(example).is_file()]

    def generate(self, *, prune: bool) -> list[str]:
        """Trace every example without a stored trace; drop traces nothing uses."""
        errors = []
        wanted = {}
        for example in self.examples:
            wanted.setdefault(self.path(example), example)
        self.directory.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(prefix='course-visualizations-') as scratch:
            source = Path(scratch) / 'snippet.cpp'
            for target, example in wanted.items():
                if target.is_file():
                    continue
                print(f'visualizations: tracing {example.path.relative_to(self.repo)}:'
                      f'{example.tag.line}', flush=True)
                source.write_text(example.tag.source.source + '\n', encoding='utf-8')
                try:
                    self._store(target, self.tracer.trace(source, example.tag.template, example.tag.types))
                except VisualizationError as exc:
                    errors.append(f'{example.location(self.repo)} cannot trace: {exc}')
        if prune:
            for stale in set(self.directory.glob('*.json')) - set(wanted):
                stale.unlink()
        return errors

    def _store(self, target: Path, content: str):
        with tempfile.NamedTemporaryFile('w', encoding='utf-8', dir=target.parent,
                                         prefix='.trace-', delete=False) as output:
            temporary = Path(output.name)
            output.write(content)
        temporary.replace(target)


def check_tags(repo: Path, config, selected_paths=None) -> list[str]:
    """Tag syntax only; needs neither the toolchain nor stored traces."""
    if config.visualizations is None:
        return []
    try:
        return Traces(repo, config, selected_paths).errors
    except (VisualizationError, ValueError, OSError) as exc:
        return [str(exc)]


def validate(repo: Path, config, selected_paths=None, *, command=None) -> list[str]:
    """Read-only: tags must be well formed and each must have its trace."""
    if config.visualizations is None:
        return []
    try:
        traces = Traces(repo, config, selected_paths, command=command)
        return traces.errors + traces.missing()
    except (VisualizationError, ValueError, OSError) as exc:
        return [str(exc)]


def generate(repo: Path, config, selected_paths=None, *, command=None) -> list[str]:
    """Trace what is missing; a full run also prunes traces no tag refers to."""
    if config.visualizations is None:
        return []
    try:
        traces = Traces(repo, config, selected_paths, command=command)
        if traces.errors:
            return traces.errors
        return traces.generate(prune=selected_paths is None)
    except (VisualizationError, ValueError, OSError) as exc:
        return [str(exc)]


def ci_outputs(repo: Path, config) -> dict[str, str]:
    """What the shared CI action needs to restore traces and enter the toolchain."""
    options = config.visualizations
    if options is None:
        return {'visualizations': 'false'}
    traces = Traces(repo, config)
    return {
        'visualizations': 'true',
        'visualizations_shell': f'{repo.resolve()}#{options.shell}',
        'visualizations_traces': str(traces.directory.resolve()),
        'visualizations_cache_key': traces.cache_key(),
    }


def _run(repo: Path, operation) -> int:
    from .config import ConfigError, load_config
    try:
        errors = operation(repo, load_config(repo))
    except (ConfigError, VisualizationError) as exc:
        errors = [str(exc)]
    for error in errors:
        print(f'error: {error}', file=sys.stderr)
    if not errors:
        print('visualizations: OK')
    return 1 if errors else 0


def run_visualizations_generate(course_repo: Path, args) -> int:
    return _run(course_repo, generate)


def run_visualizations_check(course_repo: Path, args) -> int:
    return _run(course_repo, validate)
